 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Image Preview</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --surface: #ffffff;
         --surface-alt: #f8fafc;
         --text: #0f172a;
         --muted: #475569;
         --border: #dbe3ee;
         --accent: #2563eb;
         --accent-strong: #1d4ed8;
         --danger: #b42318;
         --danger-strong: #991b1b;
         --shadow: 0 24px 60px #0f172a1f;
       }

       * {
         box-sizing: border-box;
       }

       html {
         min-height: 100%;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top, #e8f0ff 0, transparent 34%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         transform: translateY(-180%);
         padding: 0.75rem 1rem;
         border: 2px solid var(--accent);
         border-radius: 999px;
         background: var(--surface);
         color: var(--accent-strong);
         text-decoration: none;
         z-index: 20;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: none;
       }

       main {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 2rem 1rem;
       }

       .preview-shell {
         width: min(100%, 68rem);
         display: grid;
         grid-template-columns: minmax(0, 1.15fr) minmax(18rem, 0.85fr);
         gap: 1.5rem;
         align-items: center;
       }

       .hero {
         padding: 1rem;
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(2rem, 4vw, 3.5rem);
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .lede {
         margin: 0;
         max-width: 42rem;
         color: var(--muted);
         font-size: 1.0625rem;
         line-height: 1.6;
       }

       .card {
         border: 1px solid var(--border);
         border-radius: 1.5rem;
         background: color-mix(in srgb, var(--surface) 92%, #eef4ff 8%);
         box-shadow: var(--shadow);
         overflow: hidden;
       }

       .preview {
         display: block;
         width: 100%;
         aspect-ratio: 4 / 3;
         object-fit: cover;
         background: linear-gradient(135deg, #cfe1ff 0%, #f0f5ff 50%, #d7e8ff 100%);
       }

       .card-body {
         padding: 1.25rem;
         display: grid;
         gap: 1rem;
       }

       .meta {
         display: grid;
         gap: 0.35rem;
       }

       .title {
         margin: 0;
         font-size: 1.15rem;
         font-weight: 700;
       }

       .details {
         margin: 0;
         color: var(--muted);
         line-height: 1.5;
       }

       .actions {
         display: flex;
         gap: 0.75rem;
         flex-wrap: wrap;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         font: inherit;
         font-weight: 700;
         padding: 0.875rem 1.25rem;
         cursor: pointer;
         transition: transform 140ms ease, background-color 140ms ease, color 140ms ease, border-color 140ms ease;
       }

       button:hover {
         transform: translateY(-1px);
       }

       button:active {
         transform: translateY(0);
       }

       button:focus-visible {
         outline: 3px solid #93c5fd;
         outline-offset: 3px;
       }

       .trigger {
         background: var(--danger);
         color: #fff;
       }

       .trigger:hover {
         background: var(--danger-strong);
       }

       .secondary {
         background: var(--surface-alt);
         color: var(--text);
         border: 1px solid var(--border);
       }

       .secondary:hover {
         background: #eef4ff;
         border-color: #bfd0ea;
       }

       dialog {
         width: min(92vw, 32rem);
         border: 1px solid var(--border);
         border-radius: 1.5rem;
         padding: 0;
         color: var(--text);
         background: var(--surface);
         box-shadow: var(--shadow);
       }

       dialog::backdrop {
         background: #0f172acc;
       }

       .dialog-content {
         padding: 1.5rem;
         display: grid;
         gap: 1rem;
       }

       .dialog-header {
         display: flex;
         align-items: flex-start;
         gap: 0.875rem;
       }

       .icon {
         flex: none;
         width: 2.75rem;
         height: 2.75rem;
         border-radius: 999px;
         display: grid;
         place-items: center;
         background: #fef3f2;
         color: var(--danger);
       }

       .icon svg {
         width: 1.25rem;
         height: 1.25rem;
       }

       .dialog-title {
         margin: 0;
         font-size: 1.35rem;
         line-height: 1.2;
       }

       .dialog-copy {
         margin: 0;
         color: var(--muted);
         line-height: 1.6;
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         gap: 0.75rem;
         flex-wrap: wrap;
       }

       .confirm {
         background: var(--danger);
         color: #fff;
       }

       .confirm:hover {
         background: var(--danger-strong);
       }

       @media (max-width: 52rem) {
         .preview-shell {
           grid-template-columns: 1fr;
         }

         .hero {
           padding: 0;
         }
       }

       @media (max-width: 40rem) {
         main {
           padding: 1rem;
         }

         .card-body,
         .dialog-content {
           padding: 1rem;
         }

         .dialog-actions,
         .actions {
           flex-direction: column;
         }

         button {
           width: 100%;
           justify-content: center;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --surface: Canvas;
           --surface-alt: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --accent: LinkText;
           --accent-strong: LinkText;
           --danger: ButtonText;
           --danger-strong: ButtonText;
         }

         .card,
         dialog {
           forced-color-adjust: auto;
         }

         button,
         dialog {
           border: 1px solid ButtonBorder;
         }

         .icon {
           background: Canvas;
           color: ButtonText;
           border: 1px solid ButtonBorder;
         }

         button:focus-visible,
         .skip-link:focus {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#content">Skip to main content</a>

     <main id="content">
       <section class="preview-shell" aria-labelledby="page-title">
         <div class="hero">
           <h1 id="page-title">Image preview</h1>
           <p class="lede">
             Review this image before keeping it in your library. If you delete it, the file will be removed permanently.
           </p>
         </div>

         <article class="card" aria-labelledby="image-title">
           <img
             class="preview"
             src="https://images.unsplash.com/photo-1493246507139-91e8fad9978e?auto=format&fit=crop&w=1200&q=80"
             alt="Desk setup with a laptop, notebook, and plant beside a bright window"
           />

           <div class="card-body">
             <div class="meta">
               <h2 id="image-title" class="title">Workspace sunset</h2>
               <p class="details">Added 2 days ago · 4.8 MB · JPG</p>
             </div>

             <div class="actions">
               <button type="button" class="trigger" aria-haspopup="dialog" aria-controls="delete-dialog">
                 Delete image
               </button>
               <button type="button" class="secondary">Download</button>
             </div>
           </div>
         </article>
       </section>
     </main>

     <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description">
       <div class="dialog-content">
         <div class="dialog-header">
           <div class="icon" aria-hidden="true">
             <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
               <path d="M12 9v4" />
               <path d="M12 17h.01" />
               <path d="M10.3 4.7 2.8 18a2 2 0 0 0 1.7 3h15a2 2 0 0 0 1.7-3l-7.5-13.3a2 2 0 0 0-3.4 0Z" />
             </svg>
           </div>

           <div>
             <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
             <p class="dialog-copy" id="delete-description">
               This will remove <strong>Workspace sunset</strong> from your library. This action cannot be undone.
             </p>
           </div>
         </div>

         <div class="dialog-actions">
           <button type="button" class="secondary" data-close>Cancel</button>
           <button type="button" class="confirm" data-confirm>Delete permanently</button>
         </div>
       </div>
     </dialog>

     <script>
       const dialog = document.getElementById("delete-dialog");
       const trigger = document.querySelector(".trigger");
       const cancelButton = dialog.querySelector("[data-close]");
       const confirmButton = dialog.querySelector("[data-confirm]");
       let lastFocusedElement = null;

       function openDialog() {
         lastFocusedElement = document.activeElement;
         dialog.showModal();
         confirmButton.focus();
       }

       function closeDialog() {
         if (dialog.open) {
           dialog.close();
         }
       }

       trigger.addEventListener("click", openDialog);
       cancelButton.addEventListener("click", closeDialog);

       confirmButton.addEventListener("click", () => {
         closeDialog();
       });

       dialog.addEventListener("click", (event) => {
         const rect = dialog.getBoundingClientRect();
         const isInDialog =
           rect.top <= event.clientY &&
           event.clientY <= rect.top + rect.height &&
           rect.left <= event.clientX &&
           event.clientX <= rect.left + rect.width;

         if (!isInDialog) {
           closeDialog();
         }
       });

       dialog.addEventListener("close", () => {
         if (lastFocusedElement instanceof HTMLElement) {
           lastFocusedElement.focus();
         } else {
           trigger.focus();
         }
       });

       dialog.addEventListener("cancel", (event) => {
         event.preventDefault();
         closeDialog();
       });
     </script>
   </body>
 </html>

